// Leaving Search Session ID empty makes Chat start a new session on every
// message, which would spam the workspace with sessions.
// This workflow owns that decision instead: it keeps a map of
// { n8n chat sessionId -> Haystack Enterprise Platform search_session_id } in the workflow's static
// data, so the same conversation reuses one Haystack Enterprise Platform search session across
// messages, and a new one is only created the first time a given n8n chat
// session is seen.
//
// Static data is per-workflow, in-memory-backed storage that n8n persists to
// the database after each execution. It's fine for demos/small deployments,
// but it resets if you clear it manually, and it isn't shared across workers
// in a scaled/queue-mode setup. For production, replace this lookup/store
// pair with a real data store (a Data Table node, a database, Redis, etc.)
// keyed the same way.
const staticData = $getWorkflowStaticData('global');
staticData.searchSessions = staticData.searchSessions || {};

const n8nSessionId = $json.sessionId;
const existingSearchSessionId = staticData.searchSessions[n8nSessionId] || '';

return [
  {
    json: {
      ...$json,
      searchSessionId: existingSearchSessionId,
    },
  },
];

// Runs only the first time a given n8n chat session shows up (the "no
// existing search session" branch): remember the search session Haystack Enterprise Platform just
// created against this n8n chat session, so the next message in the same
// conversation reuses it instead of creating another one.
const staticData = $getWorkflowStaticData('global');
staticData.searchSessions = staticData.searchSessions || {};

const triggerData = $('When chat message received').item.json;
staticData.searchSessions[triggerData.sessionId] = $json.search_session_id;

return [
  {
    json: {
      ...triggerData,
      searchSessionId: $json.search_session_id,
    },
  },
];
